// Mirrors the C# wire types in src/ArcBox.Sdk (ControllerView.cs, GameManifest.cs, GameResults.cs, Campaigns/*.cs, Protocol/*.cs)
// as serialized by ArcJson.Options: camelCase, enums as strings, PlayerId and ProfileId as plain strings, nulls written as null
// (except the few optional additions the C# marks omit-when-null: Player/LobbyPlayer.profile, LobbyState.campaign(s), JoinResult.profile).
// test/contract.test.ts checks these against fixtures generated by the real serializer.

export type PlayerId = string;
/** `pr_` + 16 base64url characters. Opaque, never a credential. */
export type ProfileId = string;

export interface Option {
  id: string;
  label: string;
  /** Omitted from the JSON when null. */
  hint?: string;
}

interface ViewBase {
  viewId: string;
  deadlineUtc?: string | null;
  header?: string | null;
}

export interface WaitView extends ViewBase {
  kind: "wait";
  message: string;
}
export interface TextEntryView extends ViewBase {
  kind: "textEntry";
  prompt: string;
  maxLength: number;
  placeholder?: string | null;
}
export interface ChoiceView extends ViewBase {
  kind: "choice";
  prompt: string;
  options: Option[];
  allowMultiple: boolean;
  maxSelections?: number | null;
}
export interface ButtonsView extends ViewBase {
  kind: "buttons";
  prompt?: string | null;
  buttons: Option[];
}
export interface DrawView extends ViewBase {
  kind: "draw";
  prompt: string;
  colors?: string[] | null;
}

/** Shake to charge, tap to fire (ShakeView.cs). The charge lives on the phone; initialCharge (0..1) seeds it. */
export interface ShakeView extends ViewBase {
  kind: "shake";
  prompt: string;
  /** A team accent (#rrggbb), or null for the default. */
  color?: string | null;
  canFire: boolean;
  initialCharge: number;
}

/**
 * A screen defined by a game module (CustomView in ControllerView.cs). `data` is screen-specific JSON that the module
 * interprets; the phone's generic code never looks inside it.
 */
export interface CustomView extends ViewBase {
  kind: "custom";
  module: string;
  screen: string;
  data: unknown;
}

export type ControllerView = WaitView | TextEntryView | ChoiceView | ButtonsView | DrawView | ShakeView | CustomView;
export type ViewKind = ControllerView["kind"];

export interface GameManifest {
  id: string;
  name: string;
  description: string;
  minPlayers: number;
  maxPlayers: number;
  usesCampaigns: boolean;
  resumesAfterRestart: boolean;
}
export interface PlayerScore {
  playerId: PlayerId;
  name: string;
  score: number;
}
export interface GameResults {
  scores: PlayerScore[];
  message?: string | null;
}
export interface LobbyPlayer {
  id: PlayerId;
  name: string;
  isVip: boolean;
  connected: boolean;
  /** Set in profile-backed (campaign) rooms; omitted from the JSON when null. */
  profile?: ProfileId;
}
export interface LobbyState {
  code: string;
  players: LobbyPlayer[];
  selectedGameId?: string | null;
  games: GameManifest[];
  inGame: boolean;
  canStart: boolean;
  lastResults?: GameResults | null;
  /** The selected campaign and its roster; omitted from the JSON when null. */
  campaign?: LobbyCampaign;
  /** The game's campaigns to pick from; omitted from the JSON when null. */
  campaigns?: CampaignSummary[];
}
export interface JoinResult {
  code: string;
  playerId: PlayerId;
  secret: string;
  /** Only on a profile-backed seat; omitted from the JSON when null. */
  profile?: ProfileKey;
}
export interface CreateRoomResult {
  code: string;
  hostToken: string;
}

/** Server → client method names (ClientMethods.cs). */
export const ClientMethods = {
  LobbyChanged: "LobbyChanged",
  HostView: "HostView",
  ControllerView: "ControllerView",
  GameEnded: "GameEnded",
  RoomClosed: "RoomClosed",
  Kicked: "Kicked",
  /** (gameId, PackRef[]): the content packs the TV must have cached. */
  ContentRequired: "ContentRequired",
} as const;

/** Input payloads (PlayerInput.cs). Stroke points are a flat [x0, y0, x1, y1, …] list normalised to 0..1. */
export interface ButtonsInput { pressed: string }
/** `elapsedMs` is the phone-measured time from the options being painted to the tap; absent from older phones, and untrusted. */
export interface ChoiceInput { selected: string[]; elapsedMs?: number }
export interface TextEntryInput { text: string }
export interface Stroke { color: string; width: number; points: number[] }
export interface DrawInput { strokes: Stroke[] }
/** The ShakeView reply: charge 0..1 (required) and whether the player fired. */
export interface ShakeInput { charge: number; fire: boolean }

/** The CustomView reply (PlayerInput.cs): a screen-defined action and its data. */
export interface CustomInput { action: string; data?: unknown }

// ---------------------------------------------------------------- seats and profiles (Protocol/Seats.cs)

/** A profile key issued to this phone for one profile (only on a profile-backed seat). */
export interface ProfileKey { id: ProfileId; key: string; name: string }
export interface PeekRequest { code: string; profileKeys?: string[] | null }
/** How a seat is shown. The game supplies it in campaign rooms ("Aldric", "Dwarf Cleric · Lv 3"). */
export interface SeatCard { title: string; subtitle: string | null; color: string | null; portrait: string | null }
/** Exactly one is set: an existing (offline) seat, or a campaign member who has no seat yet. */
export interface SeatRef { slot: PlayerId | null; member: ProfileId | null }
export interface SeatOffer { ref: SeatRef; card: SeatCard; absent: boolean }
export interface RoomPeek {
  code: string;
  gameId: string | null;
  campaignName: string | null;
  inGame: boolean;
  offers: SeatOffer[];
  suggested: SeatOffer | null;
  canJoinNew: boolean;
}
/** Exactly one of `seat` or `newName` is set. */
export interface TakeSeatRequest { code: string; seat?: SeatRef | null; newName?: string | null; profileKeys?: string[] | null }
/** null `member` = "I'm new here", under `newName` (1–12 characters) or, without it, the seat's own name. */
export interface ClaimMemberRequest { member: SeatRef | null; profileKeys?: string[] | null; newName?: string | null }
export interface PackRef { packId: string; hash: string }

// ---------------------------------------------------------------- campaigns (Campaigns/*.cs, Protocol/Seats.cs)

export interface RosterEntry { profile: ProfileId; card: SeatCard; seatedAs: PlayerId | null; connected: boolean }
export interface LobbyCampaign { id: string; code: string; name: string; roster: RosterEntry[] }
export interface CampaignSummary { id: string; code: string; name: string; members: number; updatedUtc: string }
export type CampaignRole = "Owner" | "Player";
export interface CampaignMember { profile: ProfileId; displayName: string; role: CampaignRole; joinedUtc: string }
export interface CampaignInfo {
  id: string;
  code: string;
  gameId: string;
  name: string;
  owner: ProfileId;
  members: CampaignMember[];
  version: number;
}

// ---------------------------------------------------------------- runtime checks

/** A field type; a trailing "?" means the field may be missing or null. */
type FieldType = "string" | "number" | "boolean" | "options" | "strings" | "any";
type FieldSpec = FieldType | `${FieldType}?`;

const base = { kind: "string", viewId: "string", deadlineUtc: "string?", header: "string?" } as const;

/** Every field the server sends for each view kind, with its JSON type. */
export const VIEW_SCHEMAS: Record<ViewKind, Record<string, FieldSpec>> = {
  wait: { ...base, message: "string" },
  textEntry: { ...base, prompt: "string", maxLength: "number", placeholder: "string?" },
  choice: { ...base, prompt: "string", options: "options", allowMultiple: "boolean", maxSelections: "number?" },
  buttons: { ...base, prompt: "string?", buttons: "options" },
  draw: { ...base, prompt: "string", colors: "strings?" },
  shake: { ...base, prompt: "string", color: "string?", canFire: "boolean", initialCharge: "number" },
  custom: { ...base, module: "string", screen: "string", data: "any" },
};

const isRecord = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null && !Array.isArray(v);

const isOption = (v: unknown): v is Option =>
  isRecord(v) && typeof v.id === "string" && typeof v.label === "string" && (v.hint === undefined || v.hint === null || typeof v.hint === "string");

function matches(value: unknown, spec: FieldSpec): boolean {
  const optional = spec.endsWith("?");
  const type = spec.replace("?", "") as FieldType;
  // "any" is any JSON value, null included, but the field has to be there.
  if (type === "any") return value !== undefined;
  if (value === undefined || value === null) return optional;
  switch (type) {
    case "string": return typeof value === "string";
    case "number": return typeof value === "number";
    case "boolean": return typeof value === "boolean";
    case "options": return Array.isArray(value) && value.every(isOption);
    case "strings": return Array.isArray(value) && value.every((s) => typeof s === "string");
  }
}

function check(json: Record<string, unknown>, schema: Record<string, FieldSpec>, what: string): void {
  for (const [field, spec] of Object.entries(schema)) {
    if (!matches(json[field], spec)) {
      throw new Error(`Bad ${what}: field "${field}" should be ${spec}, got ${JSON.stringify(json[field])}`);
    }
  }
}

/** Validates a ControllerView from the server; throws on an unknown kind or a mistyped field. */
export function parseControllerView(json: unknown): ControllerView {
  if (!isRecord(json)) throw new Error("Bad view: not an object");
  const kind = json.kind;
  if (typeof kind !== "string" || !(kind in VIEW_SCHEMAS)) {
    throw new Error(`Unknown view kind: ${String(kind)}`);
  }
  check(json, VIEW_SCHEMAS[kind as ViewKind], `${kind} view`);
  return json as unknown as ControllerView;
}

const isManifest = (v: unknown): v is GameManifest =>
  isRecord(v) && typeof v.id === "string" && typeof v.name === "string" && typeof v.description === "string" &&
  typeof v.minPlayers === "number" && typeof v.maxPlayers === "number" &&
  typeof v.usesCampaigns === "boolean" && typeof v.resumesAfterRestart === "boolean";

const isAbsent = (v: unknown) => v === undefined || v === null;
const isStringOrAbsent = (v: unknown) => isAbsent(v) || typeof v === "string";

const isLobbyPlayer = (v: unknown): v is LobbyPlayer =>
  isRecord(v) && typeof v.id === "string" && typeof v.name === "string" && typeof v.isVip === "boolean" && typeof v.connected === "boolean" &&
  isStringOrAbsent(v.profile);

const isSeatCard = (v: unknown): v is SeatCard =>
  isRecord(v) && typeof v.title === "string" && isStringOrAbsent(v.subtitle) && isStringOrAbsent(v.color) && isStringOrAbsent(v.portrait);

const isRosterEntry = (v: unknown): v is RosterEntry =>
  isRecord(v) && typeof v.profile === "string" && isSeatCard(v.card) && isStringOrAbsent(v.seatedAs) && typeof v.connected === "boolean";

const isLobbyCampaign = (v: unknown): v is LobbyCampaign =>
  isRecord(v) && typeof v.id === "string" && typeof v.code === "string" && typeof v.name === "string" &&
  Array.isArray(v.roster) && v.roster.every(isRosterEntry);

const isCampaignSummary = (v: unknown): v is CampaignSummary =>
  isRecord(v) && typeof v.id === "string" && typeof v.code === "string" && typeof v.name === "string" &&
  typeof v.members === "number" && typeof v.updatedUtc === "string";

export function isGameResults(v: unknown): v is GameResults {
  return isRecord(v) && Array.isArray(v.scores) &&
    v.scores.every((s) => isRecord(s) && typeof s.playerId === "string" && typeof s.name === "string" && typeof s.score === "number") &&
    (v.message === undefined || v.message === null || typeof v.message === "string");
}

export function isLobbyState(v: unknown): v is LobbyState {
  return isRecord(v) && typeof v.code === "string" &&
    Array.isArray(v.players) && v.players.every(isLobbyPlayer) &&
    (v.selectedGameId === undefined || v.selectedGameId === null || typeof v.selectedGameId === "string") &&
    Array.isArray(v.games) && v.games.every(isManifest) &&
    typeof v.inGame === "boolean" && typeof v.canStart === "boolean" &&
    (v.lastResults === undefined || v.lastResults === null || isGameResults(v.lastResults)) &&
    (isAbsent(v.campaign) || isLobbyCampaign(v.campaign)) &&
    (isAbsent(v.campaigns) || (Array.isArray(v.campaigns) && v.campaigns.every(isCampaignSummary)));
}
